  use Veltrion\Services\AI\Orchestrator\Contracts\OrchestratorInterface; use Veltrion\Services\AI\Orchestrator\Enums\WorkflowState; class Orchestrator implements OrchestratorInterface { private FeatureAnalyzer $analyzer; public function __construct() { $this->analyzer = new FeatureAnalyzer(); } public function executeWorkflow(string $prompt, string $workflowType = 'feature', array $options = []): array { $engine = new WorkflowEngine(); return $engine->runPipeline($prompt, $workflowType, $options); } public function executeFeatureFile(string $filePath, string $workflowType = 'full', array $options = []): array { $engine = new WorkflowEngine(); return $engine->runPipeline($filePath, $workflowType, $options); } public function resumeWorkflow(string $workflowId): array { $state = WorkflowReport::loadState($workflowId); if (!$state) { return [ 'workflow_id' => $workflowId, 'status' => 'ERROR', 'message' => 'Workflow no encontrado para reanudar.' ]; } $engine = new WorkflowEngine($workflowId); $engine->transitionTo(WorkflowState::ANALYZING, "Reanudando workflow previamente interrumpido"); return [ 'workflow_id' => $workflowId, 'status' => WorkflowState::ANALYZING, 'message' => "Workflow {$workflowId} reanudado exitosamente." ]; } public function cancelWorkflow(string $workflowId): array { $state = WorkflowReport::loadState($workflowId); if (!$state) { return [ 'workflow_id' => $workflowId, 'status' => 'ERROR', 'message' => 'Workflow no encontrado para cancelar.' ]; } $engine = new WorkflowEngine($workflowId); $engine->transitionTo(WorkflowState::CANCELLED, "Workflow cancelado por el usuario"); return [ 'workflow_id' => $workflowId, 'status' => WorkflowState::CANCELLED, 'message' => "Workflow {$workflowId} cancelado limpiamente." ]; } public function getStatus(?string $workflowId = null): array { if ($workflowId !== null) { $state = WorkflowReport::loadState($workflowId); return $state ?? ['error' => "Workflow {$workflowId} no encontrado."]; } return [ 'active_workflows' =